from pathlib import Path
from datetime import datetime,timezone
sys.path.insert(0,str(Path.cwd()/'src'))
from proworksim.audit import code_identity
ROOT=Path.cwd();service_root=ROOT/'runs/qwen-service-v11-adapter';protocol=ROOT/'examples/model-v11/post-update-protocol.json';base='/data1/zhuxinrui/models/Qwen2.5-7B-Instruct-a09a35458c702b33eeacc393d103063234e8bc28'
def now():return datetime.now(timezone.utc).isoformat()
def ref(p):p=Path(p);return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
report={'source_before':code_identity(),'started_at':now(),'protocol':ref(protocol),'scope':'One independent adapter-loaded real HTTP episode; no learning-gain control; same public ModelPolicy and fixed rule reviewer.'}
assert not report['source_before']['code_dirty']
env=os.environ.copy();env.update(CUDA_VISIBLE_DEVICES='7',PYTHONPATH=str(ROOT/'src'))
cmd=[str(ROOT/'.train-venv/bin/python'),'-m','proworksim.local_model_service','--model',base,'--revision','a09a35458c702b33eeacc393d103063234e8bc28','--adapter','runs/first-decision-rl-v011-resident/adapter','--model-id','Qwen2.5-7B-Instruct+first-decision-v011','--output',str(service_root),'--port','18762','--max-batch','1']
report['service_command']=cmd
with open('/tmp/proworksim-v011-smoke-service.log','w') as log:
 server=subprocess.Popen(cmd,env=env,stdout=log,stderr=subprocess.STDOUT)
 report['service_pid']=server.pid
 try:
  opener=urllib.request.build_opener(urllib.request.ProxyHandler({}));ready=False
  for _ in range(60):
   if server.poll() is not None:raise RuntimeError('Owned inference service exited before ready')
   try:
    with opener.open('http://127.0.0.1:18762/v1/models',timeout=2) as response:data=response.read()
    (service_root/'models-response.json').write_bytes(data);ready=True;break
   except OSError:time.sleep(1)
  if not ready:raise RuntimeError('Service not ready in60sec')
  report['service_ready_at']=now();report['service_manifest']=ref(service_root/'service.json')
  run=[str(ROOT/'.venv/bin/python'),'scripts/model_development_experiment.py','--protocol',str(protocol),'--output','runs/model-post-update-v11-final','--workers','1']
  report['episode_command']=run
  with open('/tmp/proworksim-v011-smoke-episode.log','w') as episode_log:result=subprocess.run(run,env=env,stdout=episode_log,stderr=subprocess.STDOUT)
  report['episode_exit_code']=result.returncode
 finally:
  if server.poll() is None:server.terminate()
  try:server.wait(timeout=30)
  except subprocess.TimeoutExpired:server.kill();server.wait()
  stopped={'pid':server.pid,'at':now(),'exit_code':server.returncode,'action':'Terminated only the Popen handle created by this supervisor, after independent episode; other processes untouched.'}
  if service_root.exists():(service_root/'stopped.json').write_text(json.dumps(stopped,indent=2)+'\n')
  report.update(source_after=code_identity(),ended_at=now(),server_stop=stopped,protocol_after=ref(protocol))
  Path('/tmp/proworksim-v011-smoke-supervisor.json').write_text(json.dumps(report,indent=2)+'\n')
assert report['source_before']==report['source_after'] and report['protocol']==report['protocol_after']
print(json.dumps({'episode_exit_code':report['episode_exit_code'],'service_stopped':True,'source_clean_unchanged':True}))
